function safeLink(value: string) {
  if (!value) return '';
  try { const url = new URL(value); return ['https:','http:'].includes(url.protocol) ? url.href : ''; } catch { return ''; }
}
function embedUrl(item: Item) {
  const url = item.url || item.mediaUrl || '';
  if (item.source === 'youtube') {
    const match = url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{6,})/);
    return match ? 'https://www.youtube-nocookie.com/embed/' + match[1] : '';
  }
  if (item.source === 'drive') {
    const match = url.match(/\/file\/d\/([\w-]+)/) || url.match(/[?&]id=([\w-]+)/);
    return match ? 'https://drive.google.com/file/d/' + match[1] + '/preview' : '';
  }
  return '';
}
type Atmosphere = 'action' | 'romance' | 'thriller' | 'scifi' | 'emotional' | 'premium';
function getAtmosphere(item: Item): Atmosphere {
  const text = (item.category + ' ' + item.title + ' ' + item.description).toLowerCase();
  if (/(horror|thriller|suspense|crime|mystery)/.test(text)) return 'thriller';
  if (/(sci.?fi|futur|technology|tech|ai)/.test(text)) return 'scifi';
  if (/(wedding|romance|love|birthday|celebration|event)/.test(text)) return 'romance';
  if (/(emotional|drama|memorial|tribute|family)/.test(text)) return 'emotional';
  if (/(action|mass|trailer|fight|sports|adventure)/.test(text)) return 'action';
  return 'premium';
}
function PortfolioMedia({ item, onAtmosphereChange }: { item: Item; onAtmosphereChange: (value: Atmosphere | null) => void }) {
  const [runtime,setRuntime] = useState('');
  const src = item.mediaUrl || safeLink(item.url || '');
  const embed = embedUrl(item);
  const atmosphere = getAtmosphere(item);
  const handlePlay = (current: HTMLVideoElement) => {
    document.querySelectorAll('video').forEach(video=>{if(video!==current)video.pause();});
    onAtmosphereChange(atmosphere);
  };
  if (embed) return <iframe className="work-media" src={embed} title={item.title} loading="lazy" tabIndex={0} onFocus={()=>onAtmosphereChange(atmosphere)} onPointerDownCapture={()=>onAtmosphereChange(atmosphere)} onBlur={()=>onAtmosphereChange(null)} allow="autoplay; encrypted-media; picture-in-picture" allowFullScreen />;
  if (item.kind === 'video' && src) return <div className="work-video-runtime"><video className="work-media" src={src} controls playsInline preload="metadata" onLoadedMetadata={e=>{const media=e.currentTarget;if(!media)return;const seconds=media.duration;setRuntime(Number.isFinite(seconds)?String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0'):'');}} onPlay={e=>handlePlay(e.currentTarget)} onPause={()=>onAtmosphereChange(null)} onEnded={()=>onAtmosphereChange(null)} />{runtime&&<span className="work-runtime-badge">RUNTIME {runtime}</span>}</div>;
  if (item.kind === 'image' && src) return <img className="work-media" src={src} alt={item.title} loading="lazy" />;
  return <div className="work-placeholder"><Play size={25} /><span>PROJECT PREVIEW</span></div>;
}
